@import "tailwindcss";
@import "tw-animate-css";

@theme inline {
  @keyframes accordion-down {
    from {
      height: 0;
    }
    to {
      height: var(--radix-accordion-content-height, var(--accordion-panel-height, auto));
    }
  }

  @keyframes accordion-up {
    from {
      height: var(--radix-accordion-content-height, var(--accordion-panel-height, auto));
    }
    to {
      height: 0;
    }
  }
}

@custom-variant data-open {
  &:where([data-state="open"]),
  &:where([data-open]:not([data-open="false"])) {
    @slot;
  }
}

@custom-variant data-closed {
  &:where([data-state="closed"]),
  &:where([data-closed]:not([data-closed="false"])) {
    @slot;
  }
}

@custom-variant data-checked {
  &:where([data-state="checked"]),
  &:where([data-checked]:not([data-checked="false"])) {
    @slot;
  }
}

@custom-variant data-unchecked {
  &:where([data-state="unchecked"]),
  &:where([data-unchecked]:not([data-unchecked="false"])) {
    @slot;
  }
}

@custom-variant data-selected {
  &:where([data-selected="true"]) {
    @slot;
  }
}

@custom-variant data-disabled {
  &:where([data-disabled="true"]),
  &:where([data-disabled]:not([data-disabled="false"])) {
    @slot;
  }
}

@custom-variant data-active {
  &:where([data-state="active"]),
  &:where([data-active]:not([data-active="false"])) {
    @slot;
  }
}

@custom-variant data-horizontal {
  &:where([data-orientation="horizontal"]) {
    @slot;
  }
}

@custom-variant data-vertical {
  &:where([data-orientation="vertical"]) {
    @slot;
  }
}

@utility no-scrollbar {
  -ms-overflow-style: none;
  scrollbar-width: none;

  &::-webkit-scrollbar {
    display: none;
  }
}

@custom-variant dark (&:is(.dark *));

@keyframes scraps-toast-spin {
  to {
    transform: rotate(360deg);
  }
}

@theme inline {
  /* Fonts */
  --font-sans: "Rubik", system-ui, sans-serif;
  --font-mono: "Roboto Mono Variable", "Roboto Mono", ui-monospace, monospace;
  --font-heading: "Dammit Sans", var(--font-sans);

  /* Core semantic colors */
  --color-background: var(--background);
  --color-foreground: var(--foreground);
  --color-card: var(--card);
  --color-card-foreground: var(--card-foreground);
  --color-popover: var(--popover);
  --color-popover-foreground: var(--popover-foreground);
  --color-primary: var(--primary);
  --color-primary-foreground: var(--primary-foreground);
  --color-secondary: var(--secondary);
  --color-secondary-foreground: var(--secondary-foreground);
  --color-muted: var(--muted);
  --color-muted-foreground: var(--muted-foreground);
  --color-accent: var(--accent);
  --color-accent-foreground: var(--accent-foreground);
  --color-destructive: var(--destructive);
  --color-destructive-foreground: var(--destructive-foreground);
  --color-border: var(--border);
  --color-input: var(--input);
  --color-ring: var(--ring);
  --color-checkbox-border: var(--checkbox-border);
  --color-checkbox-checked: var(--checkbox-checked);
  --color-checkbox-checked-chonk: var(--checkbox-checked-chonk);
  --color-checkbox-focus: var(--checkbox-focus);

  /* Sentry-specific semantic colors */
  --color-warning: var(--warning);
  --color-warning-foreground: var(--warning-foreground);
  --color-success: var(--success);
  --color-success-foreground: var(--success-foreground);
  --color-promotion: var(--promotion);
  --color-promotion-foreground: var(--promotion-foreground);

  /* On-tint readable text colors (AA-safe text on the matching tinted surface) */
  --color-info: var(--info);
  --color-promotion-strong: var(--promotion-strong);

  /* Vibrant solid backgrounds (alert rail, solid badges) + AA on-tint text */
  --color-success-vibrant: var(--success-vibrant);
  --color-danger-vibrant: var(--danger-vibrant);
  --color-success-content: var(--success-content);
  --color-danger-content: var(--danger-content);
  --color-warning-content: var(--warning-content);

  /* Debossed input tokens */
  --color-input-bg: var(--input-bg);
  --color-input-shadow: var(--input-shadow);

  /* Chonky depth — the shadow color under raised buttons */
  --color-chonk-neutral: var(--chonk-neutral);
  --color-chonk-accent: var(--chonk-accent);
  --color-chonk-danger: var(--chonk-danger);
  --color-chonk-warning: var(--chonk-warning);

  /* Chart colors — Sentry categorical palette */
  --color-chart-1: var(--chart-1);
  --color-chart-2: var(--chart-2);
  --color-chart-3: var(--chart-3);
  --color-chart-4: var(--chart-4);
  --color-chart-5: var(--chart-5);

  /* Sidebar */
  --color-sidebar: var(--sidebar);
  --color-sidebar-foreground: var(--sidebar-foreground);
  --color-sidebar-primary: var(--sidebar-primary);
  --color-sidebar-primary-foreground: var(--sidebar-primary-foreground);
  --color-sidebar-accent: var(--sidebar-accent);
  --color-sidebar-accent-foreground: var(--sidebar-accent-foreground);
  --color-sidebar-border: var(--sidebar-border);
  --color-sidebar-ring: var(--sidebar-ring);

  /* Chonk shadows — reusable across all embossed/debossed components */
  --shadow-chonk: 0 2px 0 var(--border);
  --shadow-debossed: inset 0 1px 0 0 var(--border);

  /* Chonk elevation — how far the surface sits above the chonk layer */
  --chonk-elevation: 2px;
  --chonk-elevation-xs: 1px;
  --chonk-elevation-hover: 3px;
  --chonk-elevation-hover-xs: 2px;

  /* Motion — Sentry easing curves and durations */
  --ease-smooth: cubic-bezier(0.72, 0, 0.16, 1);
  --ease-snap: cubic-bezier(0.8, -0.4, 0.5, 1);
  --ease-enter: cubic-bezier(0.24, 1, 0.32, 1);
  --ease-exit: cubic-bezier(0.64, 0, 0.8, 0);
  --duration-fast: 120ms;
  --duration-moderate: 160ms;
  --duration-slow: 240ms;

  /* Radius — Sentry base is 6px (0.375rem) */
  --radius-sm: calc(var(--radius) * 0.667);
  --radius-md: calc(var(--radius) * 0.833);
  --radius-lg: var(--radius);
  --radius-xl: calc(var(--radius) * 1.333);
  --radius-2xl: calc(var(--radius) * 2);
  --radius-3xl: calc(var(--radius) * 2.667);
  --radius-4xl: calc(var(--radius) * 2.667);
}

/*
 * Sentry Light Theme
 *
 * Backgrounds: white → off-white → light grey (depth via subtle shifts)
 * Foregrounds: purple-tinted darks (never pure black)
 * Primary: Blurple #7553FF
 */
:root {
  --radius: 0.375rem;

  /* Surfaces */
  --background: oklch(1 0 0); /* #FFFFFF */
  --foreground: oklch(0.306 0.014 297); /* #302E36 */
  --card: oklch(0.979 0 0); /* #F8F8F9 */
  --card-foreground: oklch(0.306 0.014 297); /* #302E36 */
  --popover: oklch(1 0 0); /* #FFFFFF */
  --popover-foreground: oklch(0.306 0.014 297); /* #302E36 */

  /* Primary — Blurple */
  --primary: oklch(0.58 0.241 285.2); /* #7553FF */
  --primary-foreground: oklch(1 0 0); /* #FFFFFF */

  /* Secondary */
  --secondary: oklch(0.956 0.003 286.3); /* #F0F0F2 */
  --secondary-foreground: oklch(0.306 0.014 297); /* #302E36 */

  /* Muted */
  --muted: oklch(0.979 0 0); /* #F8F8F9 */
  --muted-foreground: oklch(0.52 0.017 298.3); /* #6A6772 — 5.5:1 on white, 5.1:1 on card */

  /* Accent — hover/focus states */
  --accent: oklch(0.956 0.003 286.3); /* #F0F0F2 */
  --accent-foreground: oklch(0.306 0.014 297); /* #302E36 */

  /* Destructive — darkened for AA contrast as text on white */
  --destructive: oklch(0.519 0.21 23.6); /* #C50025 — 6.2:1 on white */
  --destructive-foreground: oklch(1 0 0); /* #FFFFFF */

  /* Borders & Inputs */
  --border: oklch(0.926 0.004 286.3); /* #E6E6E9 */
  --input: oklch(0.888 0.007 295.4); /* #DAD9DE */
  --ring: oklch(0.58 0.241 285.2); /* #7553FF (blurple) */
  --scraps-link-disabled: #878490;
  --scraps-button-secondary-surface: #ffffff;
  --scraps-button-secondary-chonk: #dad9de;
  --scraps-button-secondary-content: #181225;
  --scraps-button-primary-chonk: #5827d6;
  --scraps-button-danger-chonk: #c10000;
  --scraps-button-warning-chonk: #d59600;
  --scraps-button-transparent-content: #302e36;
  --scraps-button-transparent-hover: #10103008;
  --scraps-button-transparent-active: #0000200f;
  --scraps-button-link-content: #653de9;
  --scraps-segmented-control-focus-mask: #ffffff;
  --scraps-segmented-control-focus: #7553ff;
  --checkbox-border: #dad9de;
  --checkbox-checked: #7553ff;
  --checkbox-checked-chonk: #5827d6;
  --checkbox-focus: #7553ff;
  --scraps-checkbox-focus-mask: #ffffff;
  --radio-border: #dad9de;
  --radio-checked: #7553ff;
  --radio-checked-chonk: #5827d6;
  --radio-focus: #7553ff;
  --scraps-radio-focus-mask: #ffffff;
  --scraps-chip-background: #ffffff;
  --scraps-chip-chonk: #dad9de;
  --scraps-chip-content-primary: #181225;
  --scraps-chip-content-secondary: #6a6772;
  --scraps-chip-hover: #f8f8f9;

  /* Regular Scraps layout semantic border aliases. */
  --scraps-theme-border-primary: #dad9de;
  --scraps-theme-border-secondary: #e6e6e9;
  --scraps-theme-border-muted: #e6e6e9;
  --scraps-theme-border-accent: #7553ff;
  --scraps-theme-border-danger: #ff002b;
  --scraps-theme-border-success: #00f261;
  --scraps-theme-border-warning: #ffce00;
  --scraps-theme-border-promotion: #ff70bc;
  --scraps-hotkey-background-primary: #ffffff;
  --scraps-hotkey-background-secondary: #f8f8f9;
  --scraps-hotkey-border-primary: #dad9de;
  --scraps-hotkey-content-primary: #302e36;
  --scraps-hotkey-content-secondary: #6a6772;
  --scraps-theme-shadow-low: 0px 1px 0px 0px #0000200f;
  --scraps-theme-shadow-medium: 0px 2px 0px 1px #10103008, 0px 1px 0px 0px #10103008;
  --scraps-theme-shadow-high: 0px 4px 0px 2px #10103008, 0px 1px 0px 1px #10103008;

  /* Regular Scraps Toast semantic tokens. */
  --scraps-toast-primary: #fff;
  --scraps-toast-overlay: #fff;
  --scraps-toast-success-muted: #00b8001c;
  --scraps-toast-danger-muted: #f828081c;
  --scraps-toast-success-vibrant: #00f261;
