  --scraps-content-accent: #653de9;
  --scraps-content-promotion: #c8007e;
  --scraps-content-danger: #d50000;
  --scraps-tabs-neutral-hover: #5b5864;
  --scraps-tabs-neutral-active: #4c4954;
  --scraps-tabs-accent-hover: #5827d6;
  --scraps-tabs-accent-active: #4c0fc0;
