  --scraps-tabs-accent-selected-rest: #0000f008;
  --scraps-tabs-accent-selected-hover: #0008f012;
  --scraps-tabs-accent-selected-active: #1010f81f;
  --scraps-tabs-focus: #7553ff;
  --scraps-tabs-indicator: #7553ff;
  --scraps-select-border: #dad9de;
  --scraps-select-transparent-hover: #10103008;
  --scraps-select-surface: #ffffff;
  --scraps-select-content: #302e36;
  --scraps-select-muted: #6a6772;
  --scraps-select-disabled: #878490;
  --scraps-select-content-accent: #653de9;
  --scraps-select-vibrant-accent: #7553ff;
  --scraps-select-graphics-accent: #b7b2ff;
