  --scraps-badge-on-vibrant-light: #ffffff;
  --scraps-slider-accent-background: #7553ff;
  --scraps-slider-accent-chonk: #5827d6;
  --scraps-slider-neutral-background: #10103008;
  --scraps-slider-neutral-chonk: #dad9de;
