  --scraps-menu-list-item-overlay-border: #dad9de;
  --scraps-menu-list-item-overlay-shadow: #dad9de;
  --scraps-border-primary: #dad9de;
  --scraps-border-neutral-vibrant: #a29faa;
  --scraps-border-transparent-neutral-muted: #00002026;
  --scraps-avatar-padded-background: #fff;
  --scraps-content-warning: #a45200;
  --scraps-info-graphics-warning-vibrant: #d59600;
  --scraps-content-success: #008900;
  --scraps-inline-code-content: #c8007e;
  --scraps-inline-code-background: #f000901a;
  --scraps-inline-code-neutral-content: #302e36;
  --scraps-inline-code-neutral-background: #0000200f;
  --scraps-code-accent: #7553ff;
  --scraps-code-button-active: #0000181a;
  --scraps-code-button-hover: #0000200f;
