  --scraps-code-focus-mask: #ffffff;
  --scraps-code-tooltip-background: #ffffff;
  --scraps-code-tooltip-arrow-background: #ffffff;
  --scraps-code-tooltip-content: #302e36;
  --prism-base: #302e36;
  --prism-block-background: #f8f8f9;
  --prism-comment: #6a6772;
  --prism-function: #653de9;
  --prism-highlight-accent: #00002026;
