  --scraps-theme-gray600: #5b5864;
  --scraps-theme-gray500: #6a6772;
  --scraps-theme-gray400: #787581;
  --scraps-theme-gray300: #00002026;
  --scraps-theme-gray200: #0000181a;
  --scraps-theme-gray100: #0000200f;
  --scraps-theme-blue700: #4c0fc0;
  --scraps-theme-blue600: #5827d6;
  --scraps-theme-blue500: #653de9;
  --scraps-theme-blue400: #7553ff;
  --scraps-theme-blue300: #1008f82e;
  --scraps-theme-blue200: #1010f81f;
  --scraps-theme-blue100: #0008f012;
  --scraps-theme-pink700: #9f005f;
  --scraps-theme-pink600: #b5006f;
  --scraps-theme-pink500: #c8007e;
  --scraps-theme-pink400: #d9008d;
  --scraps-theme-pink300: #f840a852;
  --scraps-theme-pink200: #f8008829;
  --scraps-theme-pink100: #f000901a;
  --scraps-theme-red700: #ab0000;
  --scraps-theme-red600: #c10000;
  --scraps-theme-red500: #d50000;
  --scraps-theme-red400: #ff002b;
  --scraps-theme-red300: #f8483052;
  --scraps-theme-red200: #f8301030;
  --scraps-theme-red100: #f828081c;
  --scraps-theme-yellow700: #813100;
  --scraps-theme-yellow600: #934100;
  --scraps-theme-yellow500: #a45200;
  --scraps-theme-yellow400: #d59600;
  --scraps-theme-yellow300: #e8b8308c;
  --scraps-theme-yellow200: #e0a8084d;
  --scraps-theme-yellow100: #e0b01030;
  --scraps-theme-green700: #006700;
  --scraps-theme-green600: #007800;
  --scraps-theme-green500: #008900;
  --scraps-theme-green400: #009800;
  --scraps-theme-green300: #00b8104a;
  --scraps-theme-green200: #08b81833;
  --scraps-theme-green100: #00b8001c;
  --scraps-alert-info-background: #0008f012;
  --scraps-alert-info-border: #b7b2ff;
  --scraps-alert-danger-background: #f828081c;
  --scraps-alert-danger-border: #ff978f;
  --scraps-alert-warning-background: #e0b01030;
  --scraps-alert-warning-border: #edca60;
  --scraps-alert-success-background: #00b8001c;
  --scraps-alert-success-border: #7cd88a;

  /* Sentry-specific semantic — background-safe vibrant values */
  --warning: oklch(0.869 0.178 91.3); /* #FFCE00 */
  --warning-foreground: oklch(0.2 0.038 297.4); /* #181225 */
  --success: oklch(0.511 0.131 149.5); /* #1A7A3A — 5.4:1 on white */
  --success-foreground: oklch(1 0 0); /* #FFFFFF */
  --promotion: oklch(0.709 0.212 349.8); /* #FC5CB4 */
  --promotion-foreground: oklch(1 0 0); /* #FFFFFF */

  /* On-tint text colors — darker than the vibrant brand colors so text passes
     WCAG AA (4.5:1) on the matching /10 tint. Mirrors Sentry's content.* tokens. */
  --info: oklch(0.503 0.243 281); /* #653DE9 — accent text on blurple tint */
  --promotion-strong: oklch(0.515 0.232 356); /* #C8007E — promotion text on pink tint */

  /* Vibrant solids for rails/solid badges (Sentry *.vibrant) */
  --success-vibrant: #00f261; /* green.opaque800 */
  --danger-vibrant: #ff002b; /* red.opaque1000 */
  /* On-tint AA text (Sentry content.*) */
  --success-content: #007000; /* darker than Sentry #008900 to clear AA on the green tint at 12px */
  --danger-content: #d50000; /* red.opaque1100 */
  --warning-content: #a45200; /* yellow.opaque1100 — amber */

  /* Debossed input tokens — the pressed-in Sentry input look */
  --input-bg: oklch(0.07 0.01 280 / 0.03); /* ~#101030 at 3% — barely visible tint */
  --input-shadow: oklch(0.888 0.007 295.4); /* #DAD9DE — inset top shadow */
  --scraps-input-background: #10103008;
  --scraps-input-content-secondary: #6a6772;

  /* Chonky button depth tokens — the signature Sentry raised button effect */
  --chonk-neutral: oklch(0.888 0.007 295.4); /* #DAD9DE */
  --chonk-accent: oklch(0.466 0.24 285.1); /* #5827D6 */
